fn track_enum_constants(class_name: &str) -> Option<&'static [&'static str]> {
    match class_name {
        TRACK_END_REASON_CLASS => {
            Some(&["FINISHED", "LOAD_FAILED", "STOPPED", "REPLACED", "CLEANUP"])
        }
        TRACK_STATE_CLASS => Some(&[
            "INACTIVE", "LOADING", "PLAYING", "SEEKING", "STOPPING", "FINISHED",
        ]),
        MARKER_STATE_CLASS => Some(&[
            "REACHED",
            "REMOVED",
            "OVERWRITTEN",
            "BYPASSED",
            "STOPPED",
            "LATE",
            "ENDED",
        ]),
        FRIENDLY_EXCEPTION_SEVERITY_CLASS => Some(&["COMMON", "SUSPICIOUS", "FAULT"]),
        RESAMPLING_CLASS => Some(&["HIGH", "MEDIUM", "LOW"]),
        YOUTUBE_INFO_STATUS_CLASS => Some(&[
            "INFO_PRESENT",
            "REQUIRES_LOGIN",
            "DOES_NOT_EXIST",
            "CONTENT_CHECK_REQUIRED",
            "LIVE_STREAM_OFFLINE",
            "PREMIERE_TRAILER",
            "NON_EMBEDDABLE",
        ]),
        YOUTUBE_CIPHER_OPERATION_TYPE_CLASS => Some(&["SWAP", "REVERSE", "SLICE", "SPLICE"]),
        YOUTUBE_ANDROID_VERSION_CLASS => Some(&["ANDROID_11"]),
        YOUTUBE_FORMAT_INFO_CLASS => Some(&[
            "WEBM_OPUS",
            "WEBM_VORBIS",
            "MP4_AAC_LC",
            "WEBM_VIDEO_VORBIS",
            "MP4_VIDEO_AAC_LC",
        ]),
        _ => None,
    }
}

