fn stack_map_offset_delta(previous: &mut Option<usize>, target: usize) -> Result<u16> {
    let delta = match *previous {
        Some(previous) => target
            .checked_sub(previous)
            .and_then(|value| value.checked_sub(1))
            .ok_or("stack-map targets are not strictly increasing")?,
        None => target,
    };
    *previous = Some(target);
    Ok(u16::try_from(delta)?)
}

fn youtube_full_frame(
    previous: &mut Option<usize>,
    target: usize,
    locals: Vec<VerificationType>,
    stack: Vec<VerificationType>,
) -> Result<StackFrame> {
    Ok(StackFrame::FullFrame {
        frame_type: 255,
        offset_delta: stack_map_offset_delta(previous, target)?,
        locals,
        stack,
    })
}

